        assert argvs[-1][:5] == [
            "agent-browser", "--session", "h_abc", "--cdp", f"http://[::1]:{port}",
        ]
        assert "127.0.0.1" not in argvs[-1][4]

        browser.remember_dock_cdp_port(9333)
